using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace ShotOut {
static class OneDrivePrintScreenHandoff {
    internal sealed class Target {internal string Path;internal int[] ProcessIds;}
    internal static Target Find(){using(var self=Process.GetCurrentProcess()){var ids=new List<int>();string path=null;foreach(var process in Process.GetProcessesByName("OneDrive"))using(process)try{if(process.SessionId!=self.SessionId)continue;string candidate=process.MainModule.FileName;if(!String.Equals(System.IO.Path.GetFileName(candidate),"OneDrive.exe",StringComparison.OrdinalIgnoreCase)||FileVersionInfo.GetVersionInfo(candidate).CompanyName.IndexOf("Microsoft",StringComparison.OrdinalIgnoreCase)<0)continue;if(path!=null&&!String.Equals(path,candidate,StringComparison.OrdinalIgnoreCase))return null;path=candidate;ids.Add(process.Id);}catch{}return path==null?null:new Target{Path=path,ProcessIds=ids.ToArray()};}}
    internal static void Stop(Target target){using(var request=Process.Start(new ProcessStartInfo(target.Path,"/shutdown"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){request.WaitForExit(3000);}var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<10000){bool running=false;foreach(int id in target.ProcessIds)try{using(var process=Process.GetProcessById(id))if(!process.HasExited)running=true;}catch(ArgumentException){}if(!running)return;Thread.Sleep(150);}throw new IOException("OneDrive did not exit in time. No process was forced closed. Try again after your current sync activity finishes.");}
    internal static void Restart(Target target){var running=Find();if(running!=null)return;using(var process=Process.Start(new ProcessStartInfo(target.Path,"/background"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){}var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<8000){if(Find()!=null)return;Thread.Sleep(200);}throw new IOException("OneDrive did not appear after the restart request. Open OneDrive from the Start menu to resume syncing."); }
    internal static bool Run(Action stop,Func<bool> claim,Action restart){try{stop();return claim();}finally{restart();}}
}
partial class SettingsDialog {
    internal Func<bool,bool> ConfigurePrintScreen;internal Func<string> PrintScreenSetupStatus;bool updatingPrintScreenSetup;Label printScreenSetupLabel;
    void BuildPrintScreenSetupOptions(FlowLayoutPanel page){
        AddTitle(page,"Print Screen shortcut");Toggle(page,"printScreen","Use Print Screen for ShotOut region capture",Value.UsePrintScreen);
        printScreenSetupLabel=new Label{Text=Value.UsePrintScreen?"Enabled. Use setup if the key is not responding.":"Off. Turn this on to use ShotOut from the Print Screen key.",Width=550,Height=44,ForeColor=ForeColor,Margin=new Padding(0,0,0,8)};page.Controls.Add(printScreenSetupLabel);
        SettingsHelp(page,"This switch applies immediately. If the key is busy, guided setup shows the next step. You can approve a brief OneDrive restart to let ShotOut claim the key. Your other capture shortcuts stay available.",75);
        Action<bool> configure=delegate(bool enabled){if(updatingPrintScreenSetup||ConfigurePrintScreen==null)return;try{updatingPrintScreenSetup=true;bool actual=ConfigurePrintScreen(enabled);Value.UsePrintScreen=actual;checks["printScreen"].Checked=actual;printScreenSetupLabel.Text=PrintScreenSetupStatus==null?(actual?"Print Screen enabled.":"Print Screen is off."):PrintScreenSetupStatus();}finally{updatingPrintScreenSetup=false;}};
        checks["printScreen"].CheckedChanged+=delegate{configure(checks["printScreen"].Checked);};
        var setup=Button("Set up Print Screen",230);setup.AccessibleName="Set up Print Screen";setup.Click+=delegate{configure(true);};page.Controls.Add(setup);
        var check=Button("Check Print Screen",210);check.AccessibleName="Check Print Screen availability";check.Click+=delegate{MessageBox.Show(this,CheckPrintScreen==null?PrintScreenIntegration.WindowsSettingStatus(PrintScreenIntegration.WindowsSnippingEnabled()):CheckPrintScreen(),"Print Screen check",MessageBoxButtons.OK,MessageBoxIcon.Information);};page.Controls.Add(check);
        Shown+=delegate{if(PrintScreenSetupStatus!=null)printScreenSetupLabel.Text=PrintScreenSetupStatus();};
    }
}
partial class Editor {
    Func<OneDrivePrintScreenHandoff.Target> printScreenSetupTargetOverride;
    string PrintScreenFriendlyStatus(){return printScreenRegistered?"Ready. Press Print Screen to capture a region; ShotOut can stay in the tray.":Preferences.Current.UsePrintScreen?"Needs setup. Another app may have reserved the key. Choose Set up Print Screen.":"Off. Turn this on to use ShotOut from the Print Screen key.";}
    bool ApplyPrintScreenImmediately(bool enabled,out string problem){
        problem="";bool old=Preferences.Current.UsePrintScreen,wasRegistered=printScreenRegistered;
        if(enabled&&PrintScreenIntegration.WindowsSnippingEnabled()==true){problem="Windows is currently using Print Screen for its own capture tool. Open Windows keyboard settings, turn that option off, then choose Try again.";return false;}
        if(enabled&&!printScreenRegistered&&!TryRegisterCaptureShortcut(4,0x4000,(uint)Keys.PrintScreen)){problem=PrintScreenIntegration.RegistrationFailure(lastCaptureHotKeyError,PrintScreenIntegration.WindowsSnippingEnabled());return false;}
        if(!enabled)UnregisterCaptureShortcut(4);
        try{Preferences.Current.UsePrintScreen=enabled;if(!Preferences.Testing)Preferences.Current.Save(Preferences.FilePath);return true;}
        catch(Exception ex){Preferences.Current.UsePrintScreen=old;if(wasRegistered&&!printScreenRegistered)TryRegisterCaptureShortcut(4,0x4000,(uint)Keys.PrintScreen);else if(!wasRegistered&&printScreenRegistered)UnregisterCaptureShortcut(4);problem="Could not save the Print Screen setting. "+ex.Message;return false;}
    }
    bool ConfigurePrintScreenImmediately(bool enabled){
        string problem;if(ApplyPrintScreenImmediately(enabled,out problem))return Preferences.Current.UsePrintScreen;
        if(!enabled){MessageBox.Show(this,problem,"Print Screen setting",MessageBoxButtons.OK,MessageBoxIcon.Information);return Preferences.Current.UsePrintScreen;}
        using(var wizard=new Form{Text="Set up Print Screen",ClientSize=new Size(590,390),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,ShowInTaskbar=false,BackColor=Color.FromArgb(30,32,38),ForeColor=Color.FromArgb(235,238,245),Font=new Font("Segoe UI",13,FontStyle.Regular,GraphicsUnit.Pixel)}){
            var title=new Label{Text="Let ShotOut use Print Screen",Location=new Point(22,18),Size=new Size(546,36),Font=new Font("Segoe UI",20,FontStyle.Bold,GraphicsUnit.Pixel)};
            var explanation=new Label{Location=new Point(22,65),Size=new Size(546,200)};
            var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=114,Padding=new Padding(18,8,12,8),WrapContents=true};
            Func<string,int,ModernButton> button=(text,width)=>new ModernButton{Text=text,Width=width,Height=36,Margin=new Padding(3,3,5,3),Font=wizard.Font,ForeColor=wizard.ForeColor,BackColor=Color.FromArgb(43,46,54)};
            var retry=button("Try again",120);var restart=button("Restart OneDrive and enable",265);var windows=button("Open Windows keyboard settings",285);var later=button("Not now",110);
            actions.Controls.Add(retry);actions.Controls.Add(restart);actions.Controls.Add(windows);actions.Controls.Add(later);wizard.Controls.Add(explanation);wizard.Controls.Add(title);wizard.Controls.Add(actions);
            bool busy=false;OneDrivePrintScreenHandoff.Target target=null;
            Action refresh=delegate{target=printScreenSetupTargetOverride==null?OneDrivePrintScreenHandoff.Find():printScreenSetupTargetOverride();bool windowsOn=PrintScreenIntegration.WindowsSnippingEnabled()==true;windows.Visible=windowsOn||!PrintScreenIntegration.WindowsSnippingEnabled().HasValue;bool canRestart=!windowsOn&&target!=null&&lastCaptureHotKeyError==1409;restart.Visible=canRestart;explanation.Text=windowsOn?"Windows is using Print Screen for screen capture. Turn that option off in Windows keyboard settings, come back here and choose Try again. ShotOut will not change Windows settings automatically.":canRestart?"Print Screen is busy, and OneDrive is running. OneDrive may be holding the key.\n\nRestart OneDrive and enable will briefly pause syncing, let ShotOut claim Print Screen, and reopen OneDrive in the background. Your files and OneDrive settings will not be changed.\n\nOnly use this when a brief sync interruption is convenient.":"Print Screen is busy or Windows could not register it.\n\nRelease the key in another screenshot or keyboard utility, then choose Try again. Windows does not identify the owner.\n\nYour current capture shortcuts still work.\n\n"+problem;};
            retry.Click+=delegate{if(ApplyPrintScreenImmediately(true,out problem))wizard.Close();else refresh();};
            windows.Click+=delegate{try{Process.Start(new ProcessStartInfo(PrintScreenIntegration.KeyboardSettingsUri){UseShellExecute=true});}catch(Exception ex){explanation.Text="Open Windows Settings and search for Print Screen. "+ex.Message;}};
            later.Click+=delegate{wizard.Close();};wizard.CancelButton=later;wizard.FormClosing+=delegate(object sender,FormClosingEventArgs args){if(busy)args.Cancel=true;};
            restart.Click+=delegate{
                if(busy||target==null)return;var selected=target;busy=true;foreach(Control control in actions.Controls)control.Enabled=false;explanation.Text="Restarting OneDrive and setting up Print Screen…\n\nOneDrive will be reopened even if the shortcut cannot be claimed.";
                Task.Factory.StartNew(delegate{bool claimed=false;string result="";try{claimed=OneDrivePrintScreenHandoff.Run(()=>OneDrivePrintScreenHandoff.Stop(selected),()=>{return (bool)Invoke((Func<bool>)delegate{string detail;bool ok=ApplyPrintScreenImmediately(true,out detail);result=detail;return ok;});},()=>OneDrivePrintScreenHandoff.Restart(selected));if(claimed)result="Print Screen is ready. OneDrive has been asked to restart in the background.";}catch(Exception ex){result="Setup could not finish: "+ex.Message+" Check that OneDrive is running again.";}return Tuple.Create(claimed,result);}).ContinueWith(task=>{if(!wizard.IsDisposed)wizard.BeginInvoke((Action)delegate{busy=false;foreach(Control control in actions.Controls)control.Enabled=true;if(task.IsFaulted){explanation.Text="Setup could not finish. Check that OneDrive is running again.";return;}if(task.Result.Item1){wizard.Close();return;}problem=task.Result.Item2;refresh();explanation.Text=problem+"\n\nYour other capture shortcuts remain available.";});});
            };
            refresh();wizard.ShowDialog(this);
        }
        return Preferences.Current.UsePrintScreen;
    }
    public void VerifyPrintScreenSetup(List<string> report,string folder){
        Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);report.Add("PASS "+label);};
        var steps=new List<string>();check(OneDrivePrintScreenHandoff.Run(()=>steps.Add("stop"),()=>{steps.Add("claim");return true;},()=>steps.Add("restart"))&&String.Join(",",steps)=="stop,claim,restart","OneDrive handoff claims Print Screen before restarting OneDrive");
        steps.Clear();check(!OneDrivePrintScreenHandoff.Run(()=>steps.Add("stop"),()=>false,()=>steps.Add("restart"))&&steps.Last()=="restart","An unsuccessful shortcut claim still restarts OneDrive");
        steps.Clear();try{OneDrivePrintScreenHandoff.Run(()=>{throw new IOException("simulated stop failure");},()=>true,()=>steps.Add("restart"));}catch(IOException){}check(steps.SequenceEqual(new[]{"restart"}),"A shutdown failure still attempts to restore OneDrive without force killing it");
        steps.Clear();try{OneDrivePrintScreenHandoff.Run(()=>steps.Add("stop"),()=>{throw new IOException("simulated save failure");},()=>steps.Add("restart"));}catch(IOException){}check(steps.Last()=="restart","An exception while saving the shortcut still restarts OneDrive");
        bool sawWizard=false;registerCaptureHotKeyOverride=(id,mods,key)=>false;unregisterCaptureHotKeyOverride=id=>{};captureHotKeyErrorOverride=()=>1409;printScreenSetupTargetOverride=()=>new OneDrivePrintScreenHandoff.Target{Path=@"C:\test-only\OneDrive.exe",ProcessIds=new int[0]};
        try{if(PrintScreenIntegration.WindowsSnippingEnabled()!=true){using(var timer=new System.Windows.Forms.Timer{Interval=60}){timer.Tick+=delegate{var wizard=Application.OpenForms.Cast<Form>().FirstOrDefault(form=>form.Text=="Set up Print Screen");if(wizard==null)return;timer.Stop();var buttons=wizard.Controls.OfType<FlowLayoutPanel>().SelectMany(panel=>panel.Controls.OfType<Button>()).ToArray();sawWizard=buttons.Any(button=>button.Text=="Restart OneDrive and enable"&&button.Visible)&&wizard.Controls.OfType<Label>().Any(label=>label.Text.Contains("briefly pause syncing"));using(var image=new Bitmap(wizard.Width,wizard.Height)){wizard.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(folder,"guided-print-screen.png"));}buttons.Single(button=>button.Text=="Not now").PerformClick();};timer.Start();ConfigurePrintScreenImmediately(true);}check(sawWizard,"Guided setup explains the sync interruption before offering the OneDrive restart action");}}
        finally{registerCaptureHotKeyOverride=null;unregisterCaptureHotKeyOverride=null;captureHotKeyErrorOverride=null;printScreenSetupTargetOverride=null;}
        bool original=Preferences.Current.UsePrintScreen;registerCaptureHotKeyOverride=(id,mods,key)=>true;unregisterCaptureHotKeyOverride=id=>{};try{string error;if(PrintScreenIntegration.WindowsSnippingEnabled()!=true){check(ApplyPrintScreenImmediately(true,out error)&&Preferences.Current.UsePrintScreen&&printScreenRegistered,"The switch immediately registers and saves Print Screen when available");check(ApplyPrintScreenImmediately(false,out error)&&!Preferences.Current.UsePrintScreen&&!printScreenRegistered,"Turning the switch off immediately releases Print Screen");}}finally{Preferences.Current.UsePrintScreen=original;registerCaptureHotKeyOverride=null;unregisterCaptureHotKeyOverride=null;printScreenRegistered=false;}
    }
}
}
